package pca

// Differential kill test for the rule-16 (facts, relational dimensions, offer sets) and rule-17 (provenance, label receipts,
// flows, read purpose) code in intent_wb.go against the TypeScript reference (oracle-facts.ts, offer-set.ts,
// label-receipts.ts, param-provenance.ts): testdata/k042-oracleprov.json.gz is generated by
// tools/pca-audit/java-mutate/k042-oracleprov-oracle.mjs (shared with the Java suite). Validators compare the verdict
// (the reference's null reason vs refused), decisions the outcome and every result member (world, single_source, labels,
// classes, env, friction, the read-purpose lists); refusal reason TEXT is compared exactly.

import (
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"strings"
	"testing"
)

func k042OPLoad(t *testing.T) []map[string]any {
	f, err := os.Open("testdata/k042-oracleprov.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	b, err := io.ReadAll(zr)
	if err != nil {
		t.Fatal(err)
	}
	doc, err := ParseJSONLenient(b)
	if err != nil {
		t.Fatal(err)
	}
	var out []map[string]any
	for _, c := range normalizeJSON(doc.(map[string]any)["cases"]).([]any) {
		out = append(out, c.(map[string]any))
	}
	if len(out) < 1900 {
		t.Fatalf("only %d cases", len(out))
	}
	return out
}

func k042Canon(v any) string {
	s, ok := canonicalLenient(normalizeJSON(v))
	if !ok {
		return fmt.Sprintf("<%v>", v)
	}
	return s
}

func k042OPValidators() map[string]func(any) bool {
	return map[string]func(any) bool{
		"validateFactWire":         validateFactWire,
		"validateWorldPolicy":      validateWorldPolicy,
		"validateOfferPolicy":      validateOfferPolicy,
		"validateOfferSetWire":     validateOfferSetWire,
		"validateLabelsWire":       validateLabelsWire,
		"validateFlowRules":        validateFlowRules,
		"validateProvenancePolicy": validateProvenancePolicy,
		"validateProvWire":         validateProvWire,
	}
}

func TestK042OracleProvCorpus(t *testing.T) {
	validators := k042OPValidators()
	var errs []string
	var td textDiffs
	for _, c := range k042OPLoad(t) {
		name, kind := c["name"].(string), c["kind"].(string)
		func() {
			defer func() {
				if r := recover(); r != nil {
					errs = append(errs, fmt.Sprintf("%s threw %v", name, r))
				}
			}()
			var got, want string
			switch kind {
			case "fn":
				v := validators[c["fn"].(string)]
				got, want = fmt.Sprint(v(c["arg"])), fmt.Sprint(c["want"] == nil)
			case "ratio":
				a, _ := jsNum(c["a"])
				b, _ := jsNum(c["b"])
				r, ok := ratioPpm(a, b)
				if ok {
					got = k042Canon(jsNumber(r))
				} else {
					got = "null"
				}
				want = k042Canon(c["want"])
			case "flowRule":
				r, ok := flowRuleFor(k042M(c["rules"]), c["cls"].(string))
				if ok {
					got = k042Canon(r)
				} else {
					got = "null"
				}
				want = k042Canon(c["want"])
			case "flowAllowed":
				got = fmt.Sprint(flowAllowed(k042M(c["rules"]), c["cls"].(string), c["origin"].(string), c["aud"]))
				want = fmt.Sprint(c["want"])
			case "active":
				committed := c["committed"]
				cf, _ := member(committed, "facts")
				co, _ := member(committed, "offer_set")
				got, want = fmt.Sprint(intentWorldActive(cf, co, c["policy"])), fmt.Sprint(c["expect"])
			case "read":
				r := IntentReadPurposePrimitive(c["input"])
				e := k042M(c["expect"])
				got = k042Canon(map[string]any{"outcome": r["outcome"], "minimise": r["minimise"], "uncovered": r["uncovered"]})
				want = k042Canon(map[string]any{"outcome": e["outcome"], "minimise": e["minimise"], "uncovered": e["uncovered"]})
			case "world":
				r, reason := IntentWorldPrimitive(c["input"])
				e := k042M(c["expect"])
				if e["ok"] == true {
					want = "ok " + k042Canon(e["world"]) + " " + k042Canon(e["single_source"])
					got = "fail " + reason
					if r["ok"] == true {
						got = "ok " + k042Canon(r["world"]) + " " + k042Canon(r["single_source"])
					}
				} else {
					want = "fail"
					got = "fail"
					if r["ok"] == true {
						got = "ok"
					} else if reason != e["reason"] {
						td.add(fmt.Sprint(e["reason"]), reason)
					}
				}
			case "prov":
				in := k042M(c["input"])
				e := k042M(c["expect"])
				action, isMap := in["action"].(map[string]any)
				if !isMap {
					got = "deny"
					want = fmt.Sprint(e["outcome"])
					break
				}
				prov, provP := in["prov"]
				cl, clP := in["committed_labels"]
				l, lP := in["labels"]
				d := decideParamProvenance(in["aud"], in["session"], action, prov, provP, cl, clP, l, lP, in["policy"])
				fr := any(nil)
				if d.friction != "" {
					fr = d.friction
				}
				if e["outcome"] == "deny" {
					want, got = "deny", d.outcome
					if d.outcome == "deny" && d.reason != e["reason"] {
						td.add(fmt.Sprint(e["reason"]), d.reason)
					}
					break
				}
				got = strings.Join([]string{d.outcome, k042Canon(fr), k042Canon(d.labels), k042Canon(d.classes), k042Canon(d.env)}, " | ")
				want = strings.Join([]string{fmt.Sprint(e["outcome"]), k042Canon(e["friction"]), k042Canon(e["labels"]), k042Canon(e["classes"]), k042Canon(e["env"])}, " | ")
				if got == want && d.reason != "" && d.reason != e["reason"] {
					td.add(fmt.Sprint(e["reason"]), d.reason)
				}
			default:
				t.Fatalf("unknown kind %s", kind)
			}
			if got != want {
				errs = append(errs, fmt.Sprintf("%s\n    got  %.300s\n    want %.300s", name, got, want))
			}
		}()
	}
	td.finish(t)
	if len(errs) > 0 {
		if len(errs) > 40 {
			errs = errs[:40]
		}
		t.Fatalf("%d mismatches:\n%s", len(errs), strings.Join(errs, "\n"))
	}
}
